/**
 * Seed script for ግጻዌ (Gtsawie / Daily Lectionary)
 *
 * STRUCTURE — 1 block per day, 30 blocks per month:
 *   sectionId = month  (e.g. "መስከረም")
 *   subtitle  = day Ge'ez numeral (e.g. "፩")
 *   order     = day number (1..30)
 *   role      = "daily"
 *   translations.gez = all 9 slots as structured JSON string:
 *     {
 *       "commemoration": "ዝካረ: ...",
 *       "misbak_negah":  "ዘነግህ ምስባክ: ...",
 *       "gospel_negah":  "ዘነግህ ወንጌል: ...",
 *       "pauline":       "ጳውሎስ: ...",
 *       "apostles":      "ሐዋርያት: ...",
 *       "acts":          "ግብረ ሐዋርያት: ...",
 *       "misbak_qidat":  "ቅዳሴ ምስባክ: ...",
 *       "gospel_qidat":  "ዘቅዳሴ ወንጌል: ...",
 *       "anaphora":      "ቅዳሴ: ..."
 *     }
 *
 * Result: 30 blocks per month × 13 months = 390 blocks total for the year.
 * Each block = one complete day, renders as a clean single card.
 *
 * Run: node backend/scripts/seed-gtsawie.js
 */

require('dotenv').config({ path: require('path').join(__dirname, '../.env') });
const mongoose        = require('mongoose');
const LiturgicalBook  = require('../models/LiturgicalBook');
const LiturgicalBlock = require('../models/LiturgicalBlock');

// ── Constants ─────────────────────────────────────────────────────────────────
const MONTHS = [
  'መስከረም','ጥቅምት','ኅዳር','ታኅሣሥ','ጥር','የካቲት',
  'መጋቢት','ሚያዝያ','ግንቦት','ሰኔ','ሐምሌ','ነሐሴ','ጰጉሜ'
];

const DAYS_PER_MONTH = {
  'መስከረም':30,'ጥቅምት':30,'ሕዳር':30,'ታኅሣሥ':30,'ጥር':30,'የካቲት':30,
  'መጋቢት':30,'ሚያዝያ':30,'ግንቦት':30,'ሰኔ':30,'ሐምሌ':30,'ነሐሴ':30,'ጳጉሜን':6
};

const GEZ_NUMS = [
  '፩','፪','፫','፬','፭','፮','፯','፰','፱','፲',
  '፲፩','፲፪','፲፫','፲፬','፲፭','፲፮','፲፯','፲፰','፲፱','፳',
  '፳፩','፳፪','፳፫','፳፬','፳፭','፳፮','፳፯','፳፰','፳፱','፴',
];

// ── Helper: build one block from a day entry ──────────────────────────────────
// slots: { 1: text, 2: text, ..., 9: text }
function buildBlock(bookId, month, day, slots) {
  const gezNum    = GEZ_NUMS[day - 1];
  const monthIdx  = MONTHS.indexOf(month);
  const blockId   = `gtsawie-${month}-d${String(day).padStart(2,'0')}`;

  // Pack all 9 slots into a single structured JSON string stored in gez
  // The reader component will JSON.parse() this to display each slot
  const structured = JSON.stringify({
    commemoration: slots[1] || '',
    misbak_negah:  slots[2] || '',
    gospel_negah:  slots[3] || '',
    pauline:       slots[4] || '',
    apostles:      slots[5] || '',
    acts:          slots[6] || '',
    misbak_qidat:  slots[7] || '',
    gospel_qidat:  slots[8] || '',
    anaphora:      slots[9] || '',
  });

  return {
    blockId,
    bookId,
    sectionId: month,
    subtitle:  gezNum,
    order:     day,           // 1..30 — one block per day
    type:      'reading',
    role:      'daily',
    translations: { gez: structured },
    isRubric:     false,
    isResponsive: false,
    metadata: {
      enteredBy: 'seed-script',
      language:  'gez',
      notes:     `${month} ${gezNum} — full day lectionary`,
    },
  };
}

